import{_ as l,C as c,o as s,c as h,a2 as r,b as o,w as t,a as i,E as d,a3 as n}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse('{"title":"Configuration Reference","description":"Every Trash Bin Pro configuration value — the trashbin_settings table, config/trashbinpro.php fallbacks, per-egg and per-server overrides, and the resolution order.","frontmatter":{"title":"Configuration Reference","description":"Every Trash Bin Pro configuration value — the trashbin_settings table, config/trashbinpro.php fallbacks, per-egg and per-server overrides, and the resolution order."},"headers":[],"relativePath":"trash-bin-pro/configuration/reference.md","filePath":"trash-bin-pro/configuration/reference.md","lastUpdated":1785521056000}'),g={name:"trash-bin-pro/configuration/reference.md"};function p(u,e,b,m,f,v){const a=c("Mermaid");return s(),h("div",null,[e[2]||(e[2]=r('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Trash Bin Pro is configured in two places:</p><ul><li><strong>Panel admin settings</strong> — <strong>Admin → Trash Bin Pro</strong> (<code>/admin/trashbinpro</code>), stored in the <code>trashbin_settings</code> database table</li><li><strong><code>config/trashbinpro.php</code></strong> — fallback defaults used only when the table is unavailable (for example, before migrations have run)</li></ul><p>Runtime configuration is managed from the admin panel and stored in the database. The values in <code>config/trashbinpro.php</code> are the ultimate fallback and mirror the built-in defaults — you should not need to hand-edit this file in normal operation.</p><div class="info custom-block"><p class="custom-block-title">Settings cache</p><p>Every setting read goes through a 5-minute cache (keys prefixed <code>trashbin_setting:</code>, 300s TTL). Writes from the admin panel invalidate the affected key immediately, so admin changes take effect at once — but if you edit <code>trashbin_settings</code> rows directly in the database, expect up to 5 minutes of staleness (or run <code>php artisan cache:clear</code>).</p></div><hr><h2 id="global-settings" tabindex="-1">Global Settings <a class="header-anchor" href="#global-settings" aria-label="Permalink to &quot;Global Settings&quot;">​</a></h2><p>Stored as key/value rows in <code>trashbin_settings</code>; edited at <code>/admin/trashbinpro</code>. Boolean keys are stored as <code>&#39;1&#39;</code>/<code>&#39;0&#39;</code> strings and cast on read.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Valid range</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>bool</td><td><code>true</code></td><td>—</td><td>Master switch. When disabled, delete requests fall back to the stock panel behavior: files are <strong>hard deleted</strong>, nothing moves to <code>/.trash</code>.</td></tr><tr><td><code>retention_hours</code></td><td>int</td><td><code>24</code></td><td>1–8760</td><td>How long files stay in the Trash Bin before the hourly purge deletes them. 8760 hours = 1 year.</td></tr><tr><td><code>default_max_bytes_per_server</code></td><td>int (bytes)</td><td><code>0</code></td><td>0–10995116277760</td><td>Default per-server Trash Bin capacity. <code>0</code> means unlimited. The admin UI enters this in <strong>MB</strong> (<code>default_max_mb_per_server</code>); it is stored as bytes = MB × 1024 × 1024.</td></tr><tr><td><code>max_files_per_delete</code></td><td>int</td><td><code>100</code></td><td>1–10000</td><td>Safety guard: maximum number of files accepted in a single delete request.</td></tr><tr><td><code>purge_batch_size</code></td><td>int</td><td><code>200</code></td><td>50–5000</td><td>How many trash rows the purge command processes per chunk. Floored at 50 inside the command.</td></tr><tr><td><code>logging_enabled</code></td><td>bool</td><td><code>true</code></td><td>—</td><td>Whether to write Pterodactyl activity-log entries for trash/restore/purge/empty actions.</td></tr><tr><td><code>protect_trash_dir</code></td><td>bool</td><td><code>true</code></td><td>—</td><td>Prevent users from manually moving files into, or deleting, the <code>.trash</code> folder.</td></tr></tbody></table><h3 id="enabled" tabindex="-1"><code>enabled</code> <a class="header-anchor" href="#enabled" aria-label="Permalink to &quot;`enabled`&quot;">​</a></h3><p>The master switch for the whole addon. When <code>true</code>, deleting files from the file manager moves them into the server&#39;s <code>/.trash</code> directory via Wings and records them in <code>trashbin_files</code>. When <code>false</code>, the panel catches the disabled state and falls back to the original hard delete — users get stock Pterodactyl behavior, and existing trash contents are left untouched.</p><p><strong>When to change it:</strong> flip to <code>false</code> temporarily during incident response or maintenance, instead of uninstalling the addon.</p><h3 id="retention-hours" tabindex="-1"><code>retention_hours</code> <a class="header-anchor" href="#retention-hours" aria-label="Permalink to &quot;`retention_hours`&quot;">​</a></h3><p>Hours a file may sit in the Trash Bin before <code>p:trashbin:purge</code> (scheduled hourly) permanently deletes it. Retention is resolved per server (see <a href="#resolution-order">Resolution Order</a>) and is always clamped to a minimum of 1 hour at resolution time.</p><p><strong>When to change it:</strong> raise it for hosts where users frequently need older restores; lower it to bound disk usage on storage-tight nodes.</p><div class="warning custom-block"><p class="custom-block-title">Common mistake</p><p>Entering <code>0</code> expecting &quot;keep forever&quot;. The admin form rejects <code>0</code> (minimum 1), and even if a <code>0</code> reached the database the effective retention is clamped to <code>max(1, value)</code> — files would be purged on the very next hourly run. The maximum supported window is 8760 hours (1 year); there is no &quot;infinite&quot; retention.</p></div><h3 id="default-max-bytes-per-server" tabindex="-1"><code>default_max_bytes_per_server</code> <a class="header-anchor" href="#default-max-bytes-per-server" aria-label="Permalink to &quot;`default_max_bytes_per_server`&quot;">​</a></h3><p>Default Trash Bin capacity per server, in <strong>bytes</strong>. <code>0</code> = unlimited. When a cap is in effect, a single file larger than the cap is rejected (<code>FileTooLargeForTrash</code>, HTTP 409), and a delete that would push the server over its cap is rejected (<code>TrashBinFull</code>, HTTP 409).</p><p>The admin UI field is <code>default_max_mb_per_server</code> and accepts <strong>MB</strong> (0–10485760); the controller multiplies by 1048576 before storing.</p><div class="warning custom-block"><p class="custom-block-title">Common mistake</p><p>Entering raw <strong>bytes</strong> into the admin field. The field is megabytes: typing <code>536870912</code> (expecting 512 MB in bytes) is rejected by the max-10485760 validation, and a value like <code>512000000</code> MB would be nonsense. Enter MB only — <code>512</code> for a 512 MB quota.</p></div><h3 id="max-files-per-delete" tabindex="-1"><code>max_files_per_delete</code> <a class="header-anchor" href="#max-files-per-delete" aria-label="Permalink to &quot;`max_files_per_delete`&quot;">​</a></h3><p>Maximum number of files accepted in a <strong>single delete request</strong>. This is a request-size guard against pathological bulk operations, nothing more.</p><div class="warning custom-block"><p class="custom-block-title">Common mistake</p><p>Assuming this limits how many files a server&#39;s Trash Bin can hold. It does not — trash capacity is governed solely by <code>default_max_bytes_per_server</code> (and the egg/server overrides). A server can accumulate far more than 100 trashed files across many delete requests.</p></div><h3 id="purge-batch-size" tabindex="-1"><code>purge_batch_size</code> <a class="header-anchor" href="#purge-batch-size" aria-label="Permalink to &quot;`purge_batch_size`&quot;">​</a></h3><p>Rows per chunk for the hourly purge command (<code>chunkById</code>). The command floors this at 50 internally, so values below 50 are treated as 50 even if one slipped into the table.</p><p><strong>When to change it:</strong> lower it if the hourly purge causes lock contention on a busy panel database; raise it if large trash backlogs aren&#39;t clearing within the hour.</p><h3 id="logging-enabled" tabindex="-1"><code>logging_enabled</code> <a class="header-anchor" href="#logging-enabled" aria-label="Permalink to &quot;`logging_enabled`&quot;">​</a></h3><p>Controls the <code>TrashActivityLogger</code>: when <code>true</code>, trash/restore/purge/empty actions write Pterodactyl activity-log entries (<code>server:trashbinpro.*</code>). When <code>false</code>, the logger is a no-op. Files still move — only the audit trail stops.</p><h3 id="protect-trash-dir" tabindex="-1"><code>protect_trash_dir</code> <a class="header-anchor" href="#protect-trash-dir" aria-label="Permalink to &quot;`protect_trash_dir`&quot;">​</a></h3><p>When <code>true</code>, the server-side guard refuses to trash the trash directory itself and blocks users from moving files into, or deleting, the <code>.trash</code> folder through normal file-manager operations. Keep this on; disabling it lets users nest trash inside trash and corrupt the bookkeeping between Wings and the <code>trashbin_files</code> table.</p><hr><h2 id="fallback-config-file" tabindex="-1">Fallback Config File <a class="header-anchor" href="#fallback-config-file" aria-label="Permalink to &quot;Fallback Config File&quot;">​</a></h2><p><code>config/trashbinpro.php</code> mirrors the built-in defaults exactly:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;enabled&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;retention_hours&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;default_max_bytes_per_server&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;max_files_per_delete&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;purge_batch_size&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;logging_enabled&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;protect_trash_dir&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>These values are read only when the <code>trashbin_settings</code> table can&#39;t be (missing table, null row). Once migrations have run and the admin panel has been saved at least once, the database wins.</p><hr><h2 id="per-egg-and-per-server-overrides" tabindex="-1">Per-Egg and Per-Server Overrides <a class="header-anchor" href="#per-egg-and-per-server-overrides" aria-label="Permalink to &quot;Per-Egg and Per-Server Overrides&quot;">​</a></h2><p>Two additional tables override the globals for subsets of servers. In both, every override column is <strong>nullable</strong> — <code>NULL</code> means &quot;inherit from the next level down&quot;.</p><h3 id="trashbin-egg-settings" tabindex="-1"><code>trashbin_egg_settings</code> <a class="header-anchor" href="#trashbin-egg-settings" aria-label="Permalink to &quot;`trashbin_egg_settings`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>egg_id</code></td><td>unsigned int, unique</td><td>The egg this override applies to. FK → <code>eggs</code>, cascade delete.</td></tr><tr><td><code>retention_hours</code></td><td>unsigned int, nullable</td><td>Retention override for all servers of this egg (1–8760). <code>NULL</code> = inherit global.</td></tr><tr><td><code>max_bytes</code></td><td>unsigned bigint, nullable</td><td>Capacity override in bytes. <code>NULL</code> = inherit global. <code>0</code> = explicit unlimited.</td></tr></tbody></table><p>The admin UI exposes these: pick an egg, optionally set retention (hours) and/or max size (MB — converted to bytes on save), leave a field blank to inherit.</p><h3 id="trashbin-server-settings" tabindex="-1"><code>trashbin_server_settings</code> <a class="header-anchor" href="#trashbin-server-settings" aria-label="Permalink to &quot;`trashbin_server_settings`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>server_id</code></td><td>unsigned int, unique</td><td>The server this override applies to. FK → <code>servers</code>, cascade delete.</td></tr><tr><td><code>max_bytes</code></td><td>unsigned bigint, nullable</td><td>Capacity override in bytes. <code>NULL</code> = inherit. <code>0</code> = explicit unlimited.</td></tr><tr><td><code>retention_hours</code></td><td>unsigned int, nullable</td><td>Retention override. <code>NULL</code> = inherit.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The admin panel does <strong>not</strong> expose per-server rows today — there is no UI for them. They are honored at runtime if present (the resolution helpers check this table first), so they can be seeded manually or by future tooling.</p></div><hr><h2 id="resolution-order" tabindex="-1">Resolution Order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution Order&quot;">​</a></h2><p>Effective values are resolved per server, strictly: <strong>server override → egg override → global default</strong>. A non-<code>NULL</code> value at a higher level wins outright.</p>',47)),(s(),o(n,null,{default:t(()=>[d(a,{id:"mermaid-383",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BeffectiveMaxBytes%20for%20Server%5D%20--%3E%20B%7Btrashbin_server_settings%3Cbr%2F%3Emax_bytes%20set%3F%7D%0A%20%20%20%20B%20--%20%22yes%20(incl.%200)%22%20--%3E%20C%5BUse%20server%20override%5D%0A%20%20%20%20B%20--%20%22NULL%20%2F%20no%20row%22%20--%3E%20D%7Btrashbin_egg_settings%3Cbr%2F%3Emax_bytes%20set%3F%7D%0A%20%20%20%20D%20--%20%22yes%20(incl.%200)%22%20--%3E%20E%5BUse%20egg%20override%5D%0A%20%20%20%20D%20--%20%22NULL%20%2F%20no%20row%22%20--%3E%20F%5BUse%20global%3Cbr%2F%3Edefault_max_bytes_per_server%5D%0A%20%20%20%20C%20--%3E%20G%5B0%20%3D%20unlimited%5D%0A%20%20%20%20E%20--%3E%20G%0A%20%20%20%20F%20--%3E%20G%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),(s(),o(n,null,{default:t(()=>[d(a,{id:"mermaid-384",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BeffectiveRetentionHours%20for%20Server%5D%20--%3E%20B%7Btrashbin_server_settings%3Cbr%2F%3Eretention_hours%20set%3F%7D%0A%20%20%20%20B%20--%20%22yes%22%20--%3E%20C%5BUse%20server%20override%5D%0A%20%20%20%20B%20--%20%22NULL%20%2F%20no%20row%22%20--%3E%20D%7Btrashbin_egg_settings%3Cbr%2F%3Eretention_hours%20set%3F%7D%0A%20%20%20%20D%20--%20%22yes%22%20--%3E%20E%5BUse%20egg%20override%5D%0A%20%20%20%20D%20--%20%22NULL%20%2F%20no%20row%22%20--%3E%20F%5BUse%20global%20retention_hours%5D%0A%20%20%20%20C%20--%3E%20G%5BClamp%20to%20minimum%201%20hour%5D%0A%20%20%20%20E%20--%3E%20G%0A%20%20%20%20F%20--%3E%20G%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<div class="tip custom-block"><p class="custom-block-title">0 is not NULL</p><p>For capacity, an override of <code>0</code> bytes is a <strong>real value</strong> meaning &quot;unlimited for this server/egg&quot; — it short-circuits the chain and wins over lower levels. Only <code>NULL</code> (field left blank) inherits. This is how you exempt one egg from an otherwise global quota.</p></div><hr><h2 id="admin-panel-actions" tabindex="-1">Admin Panel Actions <a class="header-anchor" href="#admin-panel-actions" aria-label="Permalink to &quot;Admin Panel Actions&quot;">​</a></h2><p>All actions live at <code>/admin/trashbinpro</code> (route group protected by the standard admin middleware). The page also shows total trash usage across the fleet and the current effective settings next to their defaults.</p><table tabindex="0"><thead><tr><th>Action</th><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td>Save settings</td><td><code>POST /admin/trashbinpro</code></td><td>Validates and writes all 7 global settings to <code>trashbin_settings</code> (MB converted to bytes), busting the per-key cache.</td></tr><tr><td>Reset to defaults</td><td><code>POST /admin/trashbinpro/reset</code></td><td>Rewrites all global settings to the built-in defaults shown in the table above. Does not touch egg/server overrides or trash contents.</td></tr><tr><td>Upsert egg override</td><td><code>POST /admin/trashbinpro/egg</code></td><td>Creates or updates the <code>trashbin_egg_settings</code> row for an egg. Blank fields become <code>NULL</code> (inherit).</td></tr><tr><td>Delete egg override</td><td><code>POST /admin/trashbinpro/egg/{egg}/delete</code></td><td>Removes the egg&#39;s override row; servers of that egg fall back to globals.</td></tr><tr><td>Purge Now</td><td><code>POST /admin/trashbinpro/purge-now</code></td><td>Runs <code>p:trashbin:purge</code> on demand via Artisan. Respects per-server retention — this is <strong>not</strong> an &quot;empty everything&quot; button, it only deletes files past their effective retention window.</td></tr><tr><td>Top servers by trash usage</td><td>(display only)</td><td>Lists the 15 servers with the largest trash footprint (file count + total bytes), plus fleet-wide total bytes.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Purge Now is retention-aware</p><p>Clicking Purge Now immediately after trashing a file deletes nothing — the file hasn&#39;t exceeded its retention window yet. To force immediate removal of specific items, use Empty Trash inside the server&#39;s own file manager.</p></div><hr><h2 id="database-tables-reference" tabindex="-1">Database Tables Reference <a class="header-anchor" href="#database-tables-reference" aria-label="Permalink to &quot;Database Tables Reference&quot;">​</a></h2><p>All four tables are prefixed <code>trashbin_</code> and created by the addon&#39;s migrations.</p><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th><th>Foreign keys</th></tr></thead><tbody><tr><td><code>trashbin_files</code></td><td>One row per trashed item: <code>server_id</code>, original <code>path</code> (relative to container root, no leading slash), <code>is_file</code>, <code>size</code>, <code>mode</code>, <code>deleted_by</code>, timestamps. The on-disk file lives at <code>/.trash/{id}</code>.</td><td><code>server_id</code> → <code>servers</code> <strong>cascade delete</strong> — deleting a server drops its trash rows.</td></tr><tr><td><code>trashbin_settings</code></td><td>Global key/value settings (<code>key</code> string primary key, <code>value</code> text nullable).</td><td>none</td></tr><tr><td><code>trashbin_egg_settings</code></td><td>Per-egg overrides (<code>egg_id</code> unique; nullable <code>retention_hours</code>, <code>max_bytes</code>).</td><td><code>egg_id</code> → <code>eggs</code> <strong>cascade delete</strong>.</td></tr><tr><td><code>trashbin_server_settings</code></td><td>Per-server overrides (<code>server_id</code> unique; nullable <code>max_bytes</code>, <code>retention_hours</code>).</td><td><code>server_id</code> → <code>servers</code> <strong>cascade delete</strong>.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Cascade behavior</p><p>All three server/egg-linked tables cascade on delete. Removing a server or egg in Pterodactyl permanently erases its trash records and overrides — but the orphaned <code>/.trash</code> directory on disk goes away with the container itself, so no manual cleanup is needed on the node.</p></div>',11))])}const _=l(g,[["render",p]]);export{y as __pageData,_ as default};
